    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return getattr(self._open(), name)

    def __iter__(self):
        return iter(self._open())

    def __next__(self):
        return next(self._open())

    def close(self):
        if self._file is not None:
            self._file.close()

    def close_intelligently(self):
        self.close()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


def open_file(filename, mode="r", encoding=None, errors="strict", lazy=False, atomic=False):
    """Open a file, or a standard stream for ``-`` (FP-09, FP-11)."""
    if filename == "-":
        if any(m in mode for m in "wax"):
            stream = sys.stdout
        else:
            stream = sys.stdin
        if "b" in mode:
            stream = getattr(stream, "buffer", stream)
        return _NoCloseProxy(stream)
    if lazy:
        return LazyFile(filename, mode, encoding, errors, atomic)
    try:
        if atomic and any(m in mode for m in "wax"):
            return _AtomicWriter(filename, mode, encoding, errors)
        return open(filename, mode, **_open_kwargs(mode, encoding, errors))
    except OSError as e:
        raise FileError(format_filename(filename), f"Could not open file '{format_filename(filename)}': {e.strerror}") from e

