        return text[:limit]
    return text[: limit - 3].rstrip() + "..."


def format_dl(rows, width, col_max=30, indent=2, col_spacing=2):
    """Lay out ``(first, second)`` rows as an indented two-column list."""
    if not rows:
        return []
    first_width = min(max(len(first) for first, _ in rows), col_max)
    lines = []
    text_width = max(width - indent - first_width - col_spacing, 20)
    for first, second in rows:
        pad = " " * indent
        if not second:
            lines.append(pad + first)
            continue
        wrapped = wrap_text(second, width=text_width).split("\n")
        continuation = " " * (indent + first_width + col_spacing)
        if len(first) <= first_width:
            lines.append(pad + first.ljust(first_width) + " " * col_spacing + wrapped[0])
        else:
            lines.append(pad + first)
            lines.append(continuation + wrapped[0])
        for extra in wrapped[1:]:
            lines.append(continuation + extra)
    return lines


def format_section(title, lines):
    """A titled block, followed by a blank line."""
    return [title + ":"] + list(lines) + [""]

