"""Terminal helpers: styling, prompts, pager, progress bars, editor and launch (FP-08, FP-11)."""

import getpass
import io
import os
import shlex
import subprocess
import sys
import tempfile
import time
from contextlib import contextmanager

from ._state import current_color_flag, is_interactive, is_tty, should_strip_ansi
from .exceptions import Abort, BadParameter
from .paramtypes import convert_type
from .utils import echo, unstyle

__all__ = [
    "style",
    "unstyle",
    "secho",
    "echo_via_pager",
    "get_pager_file",
    "progressbar",
    "prompt",
    "confirm",
    "getchar",
    "pause",
    "edit",
    "launch",
    "clear",
]

_COLOR_INDEX = {
    "black": 0,
    "red": 1,
    "green": 2,
    "yellow": 3,
    "blue": 4,
    "magenta": 5,
    "cyan": 6,
    "white": 7,
}

_SWITCHES = [
    ("bold", 1),
    ("dim", 2),
    ("italic", 3),
    ("underline", 4),
    ("blink", 5),
    ("reverse", 7),
    ("strikethrough", 9),
    ("overline", 53),
]


def _color_code(color, background):
    base = 40 if background else 30
    if isinstance(color, str):
        name = color.lower()
        if name == "reset":
            return "49" if background else "39"
        if name.startswith("bright_") and name[len("bright_"):] in _COLOR_INDEX:
            return str((100 if background else 90) + _COLOR_INDEX[name[len("bright_"):]])
        if name in _COLOR_INDEX:
            return str(base + _COLOR_INDEX[name])
        raise TypeError(f"Unknown color {color!r}.")
    prefix = "48" if background else "38"
    if isinstance(color, int) and not isinstance(color, bool) and 0 <= color <= 255:
        return f"{prefix};5;{color}"
    if (isinstance(color, (list, tuple)) and len(color) == 3
            and all(isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255 for c in color)):
        return f"{prefix};2;{color[0]};{color[1]};{color[2]}"
    raise TypeError(f"Invalid color {color!r}.")


def style(text, fg=None, bg=None, bold=None, dim=None, underline=None, overline=None, italic=None,
          blink=None, reverse=None, strikethrough=None, reset=True):
    """Wrap ``text`` in ANSI SGR sequences (FP-11)."""
    bits = []
    if fg is not None:
        bits.append(_color_code(fg, background=False))
    if bg is not None:
        bits.append(_color_code(bg, background=True))
    flags = {
        "bold": bold,
        "dim": dim,
        "italic": italic,
        "underline": underline,
        "overline": overline,
        "blink": blink,
        "reverse": reverse,
        "strikethrough": strikethrough,
    }
    for name, code in _SWITCHES:
        if flags.get(name):
            bits.append(str(code))
    if not bits:
        return text
    out = "\x1b[" + ";".join(bits) + "m" + text
    if reset:
        out += "\x1b[0m"
    return out


def secho(message=None, file=None, nl=True, err=False, color=None, **styles):
    """``echo`` of a styled message."""
    if message is not None:
        message = style(str(message), **styles)
    echo(message, file=file, nl=nl, err=err, color=color)


# -- pager ---------------------------------------------------------------

def _pager_command():
    return os.environ.get("PAGER")


def echo_via_pager(text_or_generator, color=None):
    """Write long text through the pager when the session is interactive (FP-11)."""
    text = text_or_generator
    if callable(text):
        text = text()
    chunks = [text] if isinstance(text, str) else text
    pager = _pager_command()
    if not is_interactive() or not pager:
        for chunk in chunks:
            echo(chunk, nl=False, color=color)
        return
    strip = color is False or (color is None and current_color_flag() is False)
    proc = subprocess.Popen(shlex.split(pager), stdin=subprocess.PIPE)
    stream = io.TextIOWrapper(proc.stdin, encoding="utf-8", errors="replace")
    try:
        for chunk in chunks:
            if strip:
                chunk = unstyle(chunk)
            stream.write(chunk)
            stream.flush()
    finally:
        stream.close()
        proc.wait()


@contextmanager
def get_pager_file(color=None):
    """Writable text stream that goes through the pager when interactive (FP-11)."""
    pager = _pager_command()
    if not is_interactive() or not pager:
        yield sys.stdout
        return
    proc = subprocess.Popen(shlex.split(pager), stdin=subprocess.PIPE)
    stream = io.TextIOWrapper(proc.stdin, encoding="utf-8", errors="replace")
    try:
        yield stream
    finally:
        stream.close()
        proc.wait()


# -- progress bar --------------------------------------------------------

class ProgressBar:
    """Iterable progress indicator. Items are always visited, in order (FP-11)."""

    def __init__(self, iterable, length, label, hidden, width=36):
        self.iterable = iterable
        if length is None and iterable is not None:
            try:
                length = len(iterable)
            except TypeError:
                length = None
        self.length = length
        self.label = label
        self.hidden = hidden
        self.width = width
        self.pos = 0
        self.start = time.time()
        self.visible = (not hidden) and is_tty(sys.stdout)
        self._printed_label = False

    def __enter__(self):
        if self.label and not self.hidden and not self.visible:
            echo(self.label)
            self._printed_label = True
        self.render()
        return self

    def __exit__(self, *exc):
        if self.visible:
            self.render(final=True)
            echo("")
        return False

    def __iter__(self):
        for item in self.iterable or ():
            yield item
            self.update(1)

    def update(self, n_steps):
        self.pos += n_steps
        self.render()

    def eta_seconds(self):
        if not self.length or self.pos == 0:
            return None
        elapsed = time.time() - self.start
        return (self.length - self.pos) * elapsed / self.pos

    def render(self, final=False):
        if not self.visible:
            return
        label = self.label or ""
        if self.length:
            done = min(self.pos / self.length, 1.0)
            filled = int(self.width * done)
            bar = "#" * filled + "-" * (self.width - filled)
            eta = self.eta_seconds() or 0 if not final else 0
            line = f"\r{label}  [{bar}]  {self.pos}/{self.length}  eta {int(eta)}s"
        else:
            line = f"\r{label}  {self.pos}"
        echo(line, nl=False)


