    """Context manager yielding a progress bar (FP-11)."""
    return ProgressBar(iterable, length, label, hidden, width=options.get("width", 36))


# -- prompts and input -----------------------------------------------------

def _read_line(prompt_text, hide=False, err=False, echo_input=True):
    stream_out = sys.stderr if err else sys.stdout
    stdin = sys.stdin
    if is_tty(stdin) and hide:
        return getpass.getpass(prompt_text)
    echo(prompt_text, nl=False, err=err)
    stream_out.flush()
    line = stdin.readline()
    if line == "":
        raise Abort()
    text = line.rstrip("\r\n")
    if echo_input and not hide and not is_tty(stdin):
        echo(text)
    return text


def prompt(text, default=None, hide_input=False, confirmation_prompt=False, type=None, value_proc=None,
           prompt_suffix=": ", show_default=True, err=False, show_choices=True):
    """Ask for a value; re-asks on conversion failure (FP-08)."""
    if callable(default):
        default = default()
    if value_proc is None:
        ty = convert_type(type, default)

        def value_proc(raw):
            return ty.convert(raw, None, None)

    shown = ""
    if show_default and default is not None and not hide_input:
        shown = f" [{default}]"
    prompt_text = f"{text}{shown}{prompt_suffix}"
    while True:
        raw = _read_line(prompt_text, hide=hide_input, err=err)
        if raw == "":
            if default is None:
                continue
            raw_value = default
            try:
                result = value_proc(raw_value)
            except BadParameter as e:
                echo(f"Error: {e.format_message()}", err=True)
                continue
        else:
            try:
                result = value_proc(raw)
            except BadParameter as e:
                echo(f"Error: {e.format_message()}", err=True)
                continue
        if confirmation_prompt:
            again = _read_line("Repeat for confirmation" + prompt_suffix, hide=hide_input, err=err)
            if again != raw:
                echo("Error: The two entered values do not match.", err=True)
                continue
        return result


def confirm(text, default=False, abort=False, prompt_suffix=": ", show_default=True, err=False):
    """Ask a yes/no question and return a boolean (FP-08)."""
    if show_default:
        choices = "[Y/n]" if default else "[y/N]"
        prompt_text = f"{text} {choices}{prompt_suffix}"
    else:
        prompt_text = f"{text}{prompt_suffix}"
    while True:
        answer = _read_line(prompt_text, err=err).strip().lower()
        if answer in ("y", "yes"):
            result = True
            break
        if answer in ("n", "no"):
            result = False
            break
        if answer == "":
            result = bool(default)
            break
        echo("Error: invalid input", err=True)
    if abort and not result:
        raise Abort()
    return result


def getchar(echo=False):
    """Read one character from the terminal, even if stdin is a pipe (FP-11)."""
    try:
        import termios
        import tty

        fd = os.open("/dev/tty", os.O_RDWR)
    except (ImportError, OSError):
        fd = None
    if fd is None:
        char = sys.stdin.read(1)
    else:
        try:
            old = termios.tcgetattr(fd)
            try:
                tty.setraw(fd)
                char = os.read(fd, 1).decode("utf-8", "replace")
            finally:
                termios.tcsetattr(fd, termios.TCSADRAIN, old)
        finally:
            os.close(fd)
    if char == "\x03":
        raise KeyboardInterrupt()
    if char in ("\x04", "\x1a", ""):
        raise EOFError()
    if echo:
        globals()["echo"](char, nl=False)
    return char


def pause(info=None, err=False):
    """Wait for a key when interactive; do nothing otherwise (FP-11)."""
    if not is_interactive():
        return
    if info is None:
        info = "Press any key to continue..."
    echo(info, nl=False, err=err)
    try:
        getchar()
    except (KeyboardInterrupt, EOFError):
        pass
    echo("", err=err)


def edit(text=None, editor=None, env=None, require_save=True, extension=".txt", filename=None):
    """Open a file in an editor; returns the saved text, or None (FP-11)."""
    if editor is None:
        editor = os.environ.get("VISUAL") or os.environ.get("EDITOR")
    if editor is None:
        editor = "notepad" if sys.platform.startswith("win") else "vi"
    merged_env = dict(os.environ)
    if env:
        merged_env.update(env)
    if filename is not None:
        subprocess.call(shlex.split(editor) + [str(filename)], env=merged_env)
        return None
    original = text or ""
    fd, path = tempfile.mkstemp(suffix=extension)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(original)
        subprocess.call(shlex.split(editor) + [path], env=merged_env)
        with open(path, encoding="utf-8", newline="") as handle:
            saved = handle.read()
    finally:
        os.remove(path)
    if require_save and saved == original:
        return None
    return saved


def launch(url, wait=False, locate=False):
    """Open a URL or file with the default application; returns a status (FP-11)."""
    if sys.platform.startswith("win"):
        os.startfile(url)  # noqa: S606 - documented Windows behaviour
        return 0
    if sys.platform == "darwin":
        command = ["open"] + (["-R"] if locate else []) + [url]
    else:
        command = ["xdg-open", url]
    try:
        proc = subprocess.Popen(command)
    except OSError:
        return 127
    if wait:
        return proc.wait()
    return 0


def clear():
    """Clear the visible terminal; nothing when not connected to one (FP-11)."""
    if is_tty(sys.stdout):
        sys.stdout.write("\033[2J\033[H")
        sys.stdout.flush()

