        if answer in ("n", "no"):
            result = False
            break
        if answer == "":
            result = bool(default)
            break
        echo("Error: invalid input", err=True)
    if abort and not result:
        raise Abort()
    return result


def getchar(echo=False):
    """Read one character from the terminal, even if stdin is a pipe (FP-11)."""
    try:
        import termios
        import tty

        fd = os.open("/dev/tty", os.O_RDWR)
    except (ImportError, OSError):
        fd = None
    if fd is None:
        char = sys.stdin.read(1)
    else:
        try:
            old = termios.tcgetattr(fd)
            try:
                tty.setraw(fd)
                char = os.read(fd, 1).decode("utf-8", "replace")
            finally:
                termios.tcsetattr(fd, termios.TCSADRAIN, old)
        finally:
            os.close(fd)
    if char == "\x03":
        raise KeyboardInterrupt()
    if char in ("\x04", "\x1a", ""):
        raise EOFError()
    if echo:
        globals()["echo"](char, nl=False)
    return char


def pause(info=None, err=False):
    """Wait for a key when interactive; do nothing otherwise (FP-11)."""
    if not is_interactive():
        return
    if info is None:
        info = "Press any key to continue..."
    echo(info, nl=False, err=err)
    try:
        getchar()
    except (KeyboardInterrupt, EOFError):
        pass
    echo("", err=err)


def edit(text=None, editor=None, env=None, require_save=True, extension=".txt", filename=None):
    """Open a file in an editor; returns the saved text, or None (FP-11)."""
    if editor is None:
        editor = os.environ.get("VISUAL") or os.environ.get("EDITOR")
    if editor is None:
        editor = "notepad" if sys.platform.startswith("win") else "vi"
    merged_env = dict(os.environ)
    if env:
        merged_env.update(env)
    if filename is not None:
        subprocess.call(shlex.split(editor) + [str(filename)], env=merged_env)
        return None
    original = text or ""
    fd, path = tempfile.mkstemp(suffix=extension)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(original)
        subprocess.call(shlex.split(editor) + [path], env=merged_env)
        with open(path, encoding="utf-8", newline="") as handle:
            saved = handle.read()
    finally:
        os.remove(path)
    if require_save and saved == original:
        return None
    return saved


def launch(url, wait=False, locate=False):
    """Open a URL or file with the default application; returns a status (FP-11)."""
    if sys.platform.startswith("win"):
        os.startfile(url)  # noqa: S606 - documented Windows behaviour
        return 0
    if sys.platform == "darwin":
        command = ["open"] + (["-R"] if locate else []) + [url]
    else:
        command = ["xdg-open", url]
    try:
        proc = subprocess.Popen(command)
    except OSError:
        return 127
    if wait:
        return proc.wait()
    return 0


def clear():
