"""Behavioural tests for Optlyn. Names cite the spec ids they exercise (see NOTES.md)."""

import enum
import os
import pathlib
import uuid

import pytest

import optlyn as o
from optlyn.formatting import wrap_text
from optlyn.testing import CliRunner

runner = CliRunner()


def invoke(cli, args=(), **kwargs):
    kwargs.setdefault("prog_name", "tool")
    return runner.invoke(cli, list(args), **kwargs)


# ---------------------------------------------------------------- FP-01 / FP-13

def test_command_name_derivation_and_run():  # spec: FP-01 naming
    @o.command()
    def sync_data_cmd():
        o.echo("synced")

    assert sync_data_cmd.name == "sync-data"
    res = invoke(sync_data_cmd)
    assert res.exit_code == 0 and res.output == "synced\n"


def test_explicit_name_only_accepts_that_name():  # spec: FP-01 explicit name
    @o.command("go")
    def run_it():
        o.echo("ran")

    assert invoke(run_it, ["go"]).output == "ran\n"
    assert invoke(run_it, ["run-it"]).exit_code == 2


def test_unknown_option_is_usage_error_and_skips_callback():  # spec: FP-03/FP-13
    calls = []

    @o.command()
    def cmd():
        calls.append(1)

    res = invoke(cmd, ["--nope"])
    assert res.exit_code == 2 and calls == []
    assert "No such option" in res.output


def test_author_clean_stop_status():  # spec: FP-13 author clean stop
    @o.command()
    def stop():
        o.get_current_context().exit(4)
        o.echo("never")

    res = invoke(stop)
    assert res.exit_code == 4 and "never" not in res.output


def test_abort_exit_status_and_message():  # spec: FP-13 abort
    @o.command()
    def boom():
        raise o.Abort()

    res = invoke(boom)
    assert res.exit_code == 1 and "Aborted!" in res.stderr


def test_standalone_off_propagates_and_returns():  # spec: FP-01 standalone off
    @o.command()
    @o.option("--n", type=int, default=2)
    def twice(n):
        return n * 2

    assert twice.main(["--n", "4"], standalone_mode=False) == 8
    with pytest.raises(o.BadParameter):
        twice.main(["--n", "x"], standalone_mode=False)


def test_deprecated_command_still_runs_and_warns():  # spec: FP-01 deprecated
