        def convert(self, value, param, ctx):
            if value.isdigit():
                self.fail("digits not allowed", param, ctx)
            return value.upper()

    def positive(text):
        value = int(text)
        if value < 1:
            raise ValueError("need positive")
        return value

    @o.command()
    @o.option("--u", type=Upper())
    @o.option("--p", type=positive)
