def _complete(cli, words, cword=None, shell="bash"):
    line = " ".join(words)
    env = {"COMP_WORDS": line, "COMP_CWORD": str(len(words) - 1 if cword is None else cword)}
    if shell == "fish":
        env["COMP_CWORD"] = words[-1]
    env["_TOOL_COMPLETE"] = f"{shell}_complete"
    return runner.invoke(cli, [], prog_name="tool", env=env)


