def test_resource_closed_when_invocation_ends(tmp_path):  # spec: FP-07 resource cleanup
    closed = []

    class Res:
        def __enter__(self):
            return self

        def __exit__(self, *exc):
            closed.append(True)

    @o.group()
    @o.pass_context
    def grp(ctx):
        ctx.with_resource(Res())

    @grp.command()
    def child():
        raise o.Abort()

    invoke(grp, ["child"])
    assert closed == [True]
