import re
cur=None; data={}
for line in open('CHECKLIST.md'):
    m=re.match(r'## Pack (\d+) — (.*)', line)
    if m: cur=(m.group(1), m.group(2).strip()); data[cur]=[]; continue
    m=re.match(r'- \[ \] (N-\d+)', line)
    if m and cur: data[cur].append(int(m.group(1)[2:]))
total=0
