import optlyn as o
from optlyn.testing import CliRunner
r = CliRunner()
@o.group()
@o.argument("name")
@o.option("--gopt")
def grp(name, gopt):
    o.echo(f"group name={name} gopt={gopt}")
@grp.command()
@o.option("--sopt")
@o.argument("rest", nargs=-1)
def sub(sopt, rest):
    o.echo(f"sub sopt={sopt} rest={rest}")
res = r.invoke(grp, ["bob", "--gopt", "g", "sub", "--sopt", "s", "a", "b"], prog_name="t")
print(res.exit_code, repr(res.output))

@grp.group(chain=False)
def mixgrp():
    pass

@o.group(context_settings={"allow_interspersed_args": True})
@o.option("--gopt")
def mixed(gopt):
    o.echo(f"mixed gopt={gopt}")
@mixed.command()
@o.option("--sopt")
def s(sopt):
    o.echo(f"s sopt={sopt}")
print(r.invoke(mixed, ["s", "--gopt", "G", "--sopt", "S"], prog_name="t").output)

@o.command()
@o.argument("x", default="dflt")
@o.argument("y", required=False)
def opt_args(x, y):
    o.echo(f"{x}|{y}")
print(repr(r.invoke(opt_args, [], prog_name="t").output), repr(r.invoke(opt_args, ["a"], prog_name="t").output))
