def test_group_arguments_do_not_end_group_option_parsing():  # spec: FP-03 group options before subcommand
    @o.group()
    @o.argument("name")
    @o.option("--gopt")
    def grp(name, gopt):
        o.echo(f"{name}|{gopt}")

    @grp.command()
    @o.option("--sopt")
    def sub(sopt):
        o.echo(f"sub {sopt}")

    assert invoke(grp, ["bob", "--gopt", "g", "sub", "--sopt", "s"]).output == "bob|g\nsub s\n"


def test_mixing_on_group_delivers_group_option_after_subcommand():  # spec: FP-03 mixing enabled
    @o.group(context_settings={"allow_interspersed_args": True})
    @o.option("--gopt")
    def grp(gopt):
        o.echo(f"group {gopt}")

    @grp.command()
    @o.option("--sopt")
    def sub(sopt):
        o.echo(f"sub {sopt}")

    assert invoke(grp, ["sub", "--gopt", "G", "--sopt", "S"]).output == "group G\nsub S\n"


def test_optional_argument_defaults():  # spec: FP-04 optional arguments
    @o.command()
    @o.argument("x", default="dflt")
    @o.argument("y", required=False)
    def cmd(x, y):
        o.echo(f"{x}|{y}")

    assert invoke(cmd, []).output == "dflt|None\n"
    assert invoke(cmd, ["a"]).output == "a|None\n"


def test_optional_value_option_forms():  # spec: FP-03 optional value
    @o.command()
    @o.option("--opt", is_flag=False, flag_value="FLAG", default="DEF")
    def cmd(opt):
        o.echo(opt)

    assert invoke(cmd, []).output == "DEF\n"
    assert invoke(cmd, ["--opt"]).output == "FLAG\n"
    assert invoke(cmd, ["--opt", "given"]).output == "given\n"
EOF
cd /app && PYTHONPATH=src python3 -m pytest -q tests 2>&1 | tail -2

